import { cn } from '@shared/lib';

export interface PackingListSummaryData {
  projectCode?: string;
  projectName?: string;
  totalGroups: number;
  totalTagNos: number;
  totalDesignQuantity: number;
  totalPackedQuantity: number;
  packingProgressPercentage: number;
  totalDesignWeight: number;
  totalPackedWeight: number;
  weightProgressPercentage: number;
  totalReceiptQuantity: number;
  totalSiteDeliveryQuantity: number;
}

