"using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using ClosedXML.Excel;
using Contracts.Domain.Entities;
using Infrastructure.Helpers;
using ServiceDesk.Data.Entities.PackingList;
using Shared.Dto.ServiceDesk.PackingList;
using Shared.Enums;

namespace ServiceDesk.Services.Implement.PackingList;

public partial class DeliveryPackingReportService
{
    public async Task<Result<string>> ExportReportAsync(DeliveryPackingReportFilterRequest filter)
    {
        var reportResult = await GetReportAsync(filter);
        if (!reportResult.IsSuccess || reportResult.Data == null)
            return Result<string>.Failure(reportResult.Message ?? "Không thể lấy dữ liệu báo cáo để export.");

        var packages = reportResult.Data;
        if (packages.Count == 0)
            return Result<string>.Failure("Không có dữ liệu đóng kiện giao hàng để export.");

        int totalItemRows = packages.Sum(p => Math.Max(1, p.Items.Count));
        if (totalItemRows > 30_000)
            return Result<string>.Failure($"Tập dữ liệu quá lớn ({totalItemRows:N0} dòng). Vui lòng thu hẹp bộ lọc.");

        try
        {
            using var workbook = new XLWorkbook();
            var ws = workbook.Worksheets.Add("Report_DeliveryPacking");

