"import { useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { cn } from '@/lib/utils';
import { ResizableWrapTable, type ResizableWrapTableColumn } from '@shared/components';
import { Button, Combobox, NumericInput } from '@shared/ui';
import type { ReadonlyPackingDetailRow } from './packing-list-readonly-detail-table';

type Props = Readonly<{
  rows: ReadonlyPackingDetailRow[];
  uomOptions: { label: string; value: string }[];
  className?: string;
}>;

type MaterialRow = ReadonlyPackingDetailRow & { readonly _stt: number };

export function PackingListMaterialTable({ rows, uomOptions, className }: Props) {
  const { t } = useTranslation(['mechanicalPackingList', 'common']);

  const [searchText, setSearchText] = useState('');
  const [filterUOM, setFilterUOM] = useState('');
  const [filterQuantityFrom, setFilterQuantityFrom] = useState('');
  const [filterQuantityTo, setFilterQuantityTo] = useState('');
  const [filterWeightFrom, setFilterWeightFrom] = useState('');
  const [filterWeightTo, setFilterWeightTo] = useState('');

  const uomLabel = (id?: string) =>
    (id && uomOptions.find((u) => u.value === id)?.label) || id || '—';

  const getMaterialInfo = (row: ReadonlyPackingDetailRow) => {
    if (row.materialCode || row.materialName) {
      const model =
        row.modelCode && row.modelName
          ? `${row.modelCode} - ${row.modelName}`
          : row.modelName || row.modelCode || '—';
      return {
        code: row.materialCode || '—',
        name: row.materialName || row.productDescription || '—',
        model,
      };
    }
    const desc = row.productDescription || '';
    const match = desc.match(/^([^-]+)\s*-\s*([^(]+)(?:\s*\(([^)]+)\))?$/);
    if (match) {
      return {
        code: match[1].trim(),
        name: match[2].trim(),
        model: match[3]?.trim() || '—',
      };
    }
    return {
      code: '—',
      name: desc || '—',
      model: '—',
    };
  };
