   - Khai báo interface nghiêm ngặt `MaterialSourceItem`:
     ```ts
     interface MaterialSourceItem {
       id?: string;
       materialCodeSnapshot?: string | null;
       materialNameSnapshot?: string | null;
       materialModelCodeSnapshot?: string | null;
       materialModelNameSnapshot?: string | null;
       material?: { id?: string; code?: string; name?: string } | null;
       materialModel?: { id?: string; code?: string; name?: string } | null;
       model?: { id?: string; code?: string; name?: string } | null;
       semiFinishedGoodId?: string | null;
       unitOfMeasureId?: string | null;
       unitOfMeasure?: { id?: string; name?: string; symbol?: string } | null;
       quantity?: number | string | null;
       type?: number | string | null;
       description?: string | null;
       tagNo?: string | null;
       dimensionL?: number | string | null;
       dimensionW?: number | string | null;
       dimensionH?: number | string | null;
       designWeight?: number | string | null;
       remark?: string | null;
       remarks?: string | null;
       loosePartsFactoryWeight?: number | string | null;
     }
     ```
   - Hàm trích xuất dữ liệu sạch:
     ```ts
     const matName = r.materialNameSnapshot || r.material?.name || '';
     const matCode = r.materialCodeSnapshot || r.material?.code || '';
