```tsx
<RefDocumentSelector
  {...selectorProps}
  docOptions={poOptions}
  docLoading={poDropdownQuery.isLoading || poDropdownQuery.isFetching}
  onCreatorChange={
    isEditMode ? () => {} : selectorProps.onCreatorChange
