    #region Close WorkItem
    public async Task<Result> CloseAsync(Guid id)
    {
        var entity = await _repository.GetByIdAsync(id);
        if (entity == null)
            return Result.NotFound("Không tìm thấy phiếu đóng kiện giao hàng.");

        entity.IsDelivered = true;
        await _unitOfWork.SaveChangesAsync();

        var empId = (await _currentUserService.GetEmployeeIdAsync())?.ToString() ?? string.Empty;
        var orgId = (await _currentUserService.GetOrganizationIdAsync())?.ToString() ?? string.Empty;

        try
        {
            var resp = await _masterDataGrpcClient.ExecuteWorkItemTransitionAsync(new ExecuteWorkItemTransitionRequest
            {
                WorkItemId = id.ToString(),
                ActionCode = "CLOSE",
                Comment = "Đóng phiếu kiện giao hàng thành công",
                EmployeeId = empId,
                OrganizationId = orgId,
                Username = _currentUserService.Username
            });

            if (!resp.Success)
            {
                await _masterDataGrpcClient.ExecuteWorkItemTransitionAsync(new ExecuteWorkItemTransitionRequest
                {
                    WorkItemId = id.ToString(),
                    ActionCode = "COMPLETE",
                    Comment = "Đóng phiếu kiện giao hàng thành công",
                    EmployeeId = empId,
                    OrganizationId = orgId,
                    Username = _currentUserService.Username
                });
            }
        }
        catch (Exception ex)
        {
            _logger.Warning(ex, "Lỗi khi chuyển trạng thái WorkItem đóng cho FinishedGoodsDeliveryPacking {Id}", id);
        }

        return Result.Success("Đóng phiếu đóng kiện giao hàng thành công.");
    }
    #endregion
}"

